from rosterkit.models import Student


# ---
def seat_rows(students: list[Student], seats_per_row: int) -> list[str]:
    """One line of text per row, students in last name order."""
    _check_seating(students, seats_per_row)
    ordered = sorted(students, key=lambda student: student.last_name)
    chunks = _chunk(ordered, seats_per_row)
    return [_format_row(number, chunk) for number, chunk in enumerate(chunks, start=1)]


def _check_seating(students: list[Student], seats_per_row: int) -> None:
    if seats_per_row < 1:
        raise ValueError("seats_per_row must be at least one")
    if not students:
        raise ValueError("no students to seat")


def _chunk(items: list[Student], size: int) -> list[list[Student]]:
    return [items[first:first + size] for first in range(0, len(items), size)]


def _format_row(number: int, chunk: list[Student]) -> str:
    names = " | ".join(student.display_name for student in chunk)
    return f"Row {number}: {names}"

