# owner: platform

import unittest
from rosterkit.seating import seat_rows
from rosterkit.models import Student


def _make_student(last_name: str, first_name: str) -> Student:
    return Student(student_id=last_name, last_name=last_name, first_name=first_name, section="A")


class SeatRowsTests(unittest.TestCase):
    def test_one_line_per_row_in_last_name_order(self):
        students = [
            _make_student("Halloway", "Juno"),
            _make_student("Dunmere", "Piet"),
            _make_student("Quillon", "Ana"),
            _make_student("Brask", "Oli")
        ]
        self.assertEqual(
            seat_rows(students, 2),
            ["Row 1: Brask, Oli | Dunmere, Piet", "Row 2: Halloway, Juno | Quillon, Ana"]
        )

    def test_example_row_text(self):
        students = [_make_student("Halloway", "Juno"), _make_student("Dunmere", "Piet")]
        self.assertEqual(seat_rows(students, 2), ["Row 1: Dunmere, Piet | Halloway, Juno"])

    def test_last_row_can_be_partly_filled(self):
        students = [_make_student("Brask", "Oli"), _make_student("Dunmere", "Piet"), _make_student("Quillon", "Ana")]
        self.assertEqual(
            seat_rows(students, 2),
            ["Row 1: Brask, Oli | Dunmere, Piet", "Row 2: Quillon, Ana"]
        )

    def test_zero_seats_raises(self):
        students = [_make_student("Dunmere", "Piet")]
        with self.assertRaises(ValueError):
            seat_rows(students, 0)

    def test_negative_seats_raises(self):
        students = [_make_student("Dunmere", "Piet")]
        with self.assertRaises(ValueError):
            seat_rows(students, -1)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 2)
